import{_ as a,a as t,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Marketing (Admin)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/marketing.md","filePath":"api/workflows/admin/marketing.md","lastUpdated":1787725411000}'),o={name:"api/workflows/admin/marketing.md"};function n(i,e,c,d,l,u){return r(),t("div",null,e[0]||(e[0]=[s('<h1 id="marketing-admin" tabindex="-1">Marketing (Admin) <a class="header-anchor" href="#marketing-admin" aria-label="Permalink to &quot;Marketing (Admin)&quot;">​</a></h1><p>The Marketing menu spans three groups — <strong>Promotions</strong> (discount rules + coupons), <strong>Communications</strong> (email templates, events, campaigns, newsletter subscribers), and <strong>Search &amp; SEO</strong> (sitemaps, URL rewrites, search terms, search synonyms). Most are straight CRUD; this page covers the parts with real gotchas — the discount-rule reindex, the campaign send, coupon generation, and sitemap generation.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user; send as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code>. Each action is permission-gated (else <code>403</code>).</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="promotions" tabindex="-1">Promotions <a class="header-anchor" href="#promotions" aria-label="Permalink to &quot;Promotions&quot;">​</a></h2><p>Two discount-rule types plus coupons:</p><ul><li><strong><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-create.html">Catalog Rules</a></strong> — apply a discount to matching products in the catalog (price shown pre-cart). CRUD + mass-delete; <code>channels</code> + <code>customer_groups</code> + <code>conditions</code> JSON.</li><li><strong><a href="/api/rest-api/admin/marketing/promotions/cart-rules-create.html">Cart Rules</a></strong> — discount applied in the cart; CRUD + copy + mass-delete. <code>coupon_type</code> 0 (no coupon) / 1 (specific coupon).</li><li><strong>Cart Rule Coupons</strong> (sub-resource of a cart rule) — <a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-create.html">single create</a>, <a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-generate.html">bulk generate</a>, <a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons-mass-delete.html">mass-delete</a>.</li></ul><h3 id="gotcha-catalog-rule-create-update-triggers-a-full-price-reindex" tabindex="-1">Gotcha: catalog-rule create/update triggers a full price reindex <a class="header-anchor" href="#gotcha-catalog-rule-create-update-triggers-a-full-price-reindex" aria-label="Permalink to &quot;Gotcha: catalog-rule create/update triggers a full price reindex&quot;">​</a></h3><p>Creating or updating a catalog rule fires a <strong>price-index recalculation across every affected product</strong>. That job is designed to run <strong>out-of-band on a queue worker</strong> — but on a store running <code>QUEUE_CONNECTION=sync</code> it runs <strong>inline inside the request</strong> and can take tens of seconds on a large catalog, blowing past the HTTP timeout and returning a generic 500 <strong>even though the rule was already saved</strong> (query it back and it&#39;s there). This is not an API bug — it&#39;s the store&#39;s queue configuration.</p><p><strong>Handle it:</strong> the store should run <code>QUEUE_CONNECTION=redis</code> (or <code>database</code>) with a persistent <code>queue:work</code> worker, so create returns <code>201</code> instantly and the reindex runs in the background. If the client sees a timeout, re-query the rule (<a href="/api/rest-api/admin/marketing/promotions/catalog-rules-detail.html">detail</a>) before retrying — a retry would create a duplicate.</p><h3 id="coupon-bulk-generate" tabindex="-1">Coupon bulk-generate <a class="header-anchor" href="#coupon-bulk-generate" aria-label="Permalink to &quot;Coupon bulk-generate&quot;">​</a></h3><p><code>cart-rule-coupons/generate</code> takes <code>{ length (4–30), format (alphabetic|alphanumeric|numeric), prefix?, suffix?, coupon_qty (1–100) }</code> and returns the generated codes. Use it to hand out unique codes for a specific-coupon cart rule.</p><h2 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/marketing/communications/templates-create.html">Email Templates</a></strong> — reusable HTML bodies (<code>status</code> active/inactive/draft). CRUD.</li><li><strong><a href="/api/rest-api/admin/marketing/communications/events-create.html">Events</a></strong> — scheduled marketing events (a date-triggered anchor for campaigns). CRUD.</li><li><strong><a href="/api/rest-api/admin/marketing/communications/campaigns-create.html">Campaigns</a></strong> — an email blast to a customer group. CRUD + <strong><a href="/api/rest-api/admin/marketing/communications/campaigns-send.html">send</a></strong>.</li><li><strong><a href="/api/rest-api/admin/marketing/communications/subscribers-list.html">Newsletter Subscribers</a></strong> — read + toggle subscription + delete (subscriptions originate on the storefront; no admin create).</li></ul><h3 id="gotcha-campaign-send" tabindex="-1">Gotcha: campaign send <a class="header-anchor" href="#gotcha-campaign-send" aria-label="Permalink to &quot;Gotcha: campaign send&quot;">​</a></h3><p><code>POST /api/admin/marketing/campaigns/{id}/send</code> triggers the blast <strong>now</strong> — it mirrors the scheduled <code>campaign:process</code> for a single campaign but <strong>skips the event date gate</strong> (manual send = send now). Recipients resolve from the campaign&#39;s customer group: subscribed customers, or the guest subscribers list when the group is <code>guest</code>; the list is de-duped and each email is <strong>queued</strong>. An <strong>inactive campaign (<code>status=0</code>) is refused with <code>422</code></strong>. Zero recipients is success, not an error. Returns <code>{ campaignId, queued, message }</code>.</p><h2 id="search-seo" tabindex="-1">Search &amp; SEO <a class="header-anchor" href="#search-seo" aria-label="Permalink to &quot;Search &amp; SEO&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-create.html">Sitemaps</a></strong> — CRUD + <strong><a href="/api/rest-api/admin/marketing/search-seo/sitemaps-generate.html">generate</a></strong>.</li><li><strong><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites-create.html">URL Rewrites</a></strong> — 301/302 redirects; CRUD + mass-delete.</li><li><strong><a href="/api/rest-api/admin/marketing/search-seo/search-terms-list.html">Search Terms</a></strong> — storefront search analytics (read + edit redirect + delete; no create).</li><li><strong><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-create.html">Search Synonyms</a></strong> — widen search matches; CRUD + mass-delete.</li></ul><h3 id="gotcha-sitemap-generate-is-synchronous" tabindex="-1">Gotcha: sitemap generate is synchronous <a class="header-anchor" href="#gotcha-sitemap-generate-is-synchronous" aria-label="Permalink to &quot;Gotcha: sitemap generate is synchronous&quot;">​</a></h3><p><code>POST /api/admin/marketing/sitemaps/{id}/generate</code> runs the generation <strong>synchronously</strong> (the admin panel queues it) so the response carries the generated file paths + <code>generatedAt</code> immediately. For a very large catalog this can take a while. If <code>general.sitemap.settings.enabled</code> is off the job returns early — the response still succeeds but <code>indexFile</code> / <code>generatedSitemaps</code> stay empty (that usually means the config flag, not a failure).</p><h2 id="graphql-notes" tabindex="-1">GraphQL notes <a class="header-anchor" href="#graphql-notes" aria-label="Permalink to &quot;GraphQL notes&quot;">​</a></h2><p>Standard admin GraphQL: list queries use cursor pagination + explicit filter args; <strong>mass-actions and action mutations</strong> (campaign send, coupon generate, sitemap generate, mass-delete) return result objects — select the documented result fields, not a generic <code>id</code> (see the <a href="/api/workflows/admin/#graphql-the-must-know-rules">result-field rule</a>).</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p>Every call below links to its <strong>REST</strong> endpoint page for concreteness. The sequence is transport-agnostic — the same flow works over GraphQL with the equivalent query or mutation, and each REST page cross-links to its GraphQL twin. Pick whichever transport your client uses; only the request shape changes, never the order of steps.</p><p><code>200/201</code> success · <code>401</code> unauthenticated · <code>403</code> permission · <code>404</code> not found · <code>422</code> validation (duplicate coupon code, percent &gt; 100, incoherent dates, inactive campaign, bad sitemap name/path) · <code>500</code> catalog-rule reindex timeout on a <code>sync</code> queue (rule is saved — re-query, don&#39;t retry).</p>',25)]))}const p=a(o,[["render",n]]);export{g as __pageData,p as default};
